type ImplementationType = string | ModuleScript | IServiceFactory

-- 添加玩家作用域后台异步服务, 如果构造函数本身是异步加载的, 则需要使用这个
-- @param alias string? -- 别名，可选项，之后可以使用 ServiceProvider:GetService(alias) 获取服务
return function(services: IServiceCollection, implementation: ImplementationType, alias: string?)
	local ServiceDescriptor = require(script.Parent.Parent.Parent.Core.DependencyInjection.ServiceDescriptor)
	if alias then
		local lifetime = "Scoped"
		local descriptor = ServiceDescriptor.newWithVarient(alias, implementation, lifetime)
		services:Add(descriptor)
		local descriptor = ServiceDescriptor.newWithVarient("IPlayerHostedAsyncService", function(serviceProvider)
			return serviceProvider:GetRequiredService(alias)
		end, lifetime)
		services:Add(descriptor)
	else
		services:AddScoped("IPlayerHostedAsyncService", implementation)
	end
	return services
end
